  assert.deepEqual(calls[1].slice(0,4),["send-keys","-t","context-drop:worker","-l"]);assert.match(calls[1][4],/status; do not execute this as shell/);assert.deepEqual(calls[2],["send-keys","-t","context-drop:worker","Enter"]);
