  let managed=false;const gone:CommandRunner={run(command,args){if(command==="herdr"&&args.includes("get")){gets++;return{status:1,stderr:"missing"};}if(command==="herdr"&&args[2]==="workspace"&&args[3]==="list")return{status:0,stdout:JSON.stringify({result:{workspaces:managed?[{workspace_id:"new-w",label:"ContextDropManaged",focused:false}]:[]}})};if(command==="herdr"&&args.includes("list"))return{status:0,stdout:"{}"};if(command==="herdr"&&args[2]==="workspace"&&args[3]==="create"){managed=true;return{status:0,stdout:JSON.stringify({result:{workspace:{workspace_id:"new-w"},tab:{tab_id:"new-w:t1"},root_pane:{pane_id:"new-w:p1"}}})};}return{status:0};}};
